<script setup lang="ts">
import { computed, ref } from "vue"
import { useMutation, useQuery, useQueryClient } from "@tanstack/vue-query"
import { ApiError } from "../../api/client"
import { currentUserQueryOptions } from "../auth/auth"
import { getBrief, getMasterContent, getPlatformContent } from "../content/api"
import { listPublishTasks } from "../publishing/api"
import { analyticsKeys,createShortLink,createTrackingLink,getChannelSummary,listShortLinks,listTrackingLinks } from "./api"
const iso=(date:Date)=>date.toISOString().slice(0,10),today=new Date(),startDefault=new Date(today.getTime()-29*86400000)
const start=ref(iso(startDefault)),end=ref(iso(today)),country=ref(""),message=ref(""),client=useQueryClient(),user=useQuery(currentUserQueryOptions()),createOpen=ref(false),taskId=ref(""),utmSource=ref(""),utmMedium=ref("social"),utmCampaign=ref("")
const org=computed(()=>user.data.value?.organization.id??""),filters=computed(()=>({start:start.value,end:end.value,country:country.value.toUpperCase(),limit:"20",offset:"0"}))
const summary=useQuery({queryKey:computed(()=>analyticsKeys.summary(org.value,filters.value)),queryFn:()=>getChannelSummary(filters.value),enabled:computed(()=>Boolean(org.value))})
const tracking=useQuery({queryKey:computed(()=>analyticsKeys.tracking(org.value)),queryFn:listTrackingLinks,enabled:computed(()=>Boolean(org.value))})
const shorts=useQuery({queryKey:computed(()=>analyticsKeys.short(org.value)),queryFn:listShortLinks,enabled:computed(()=>Boolean(org.value))})
const published=useQuery({queryKey:computed(()=>[...analyticsKeys.all(org.value),"published"]),queryFn:listPublishTasks,enabled:computed(()=>Boolean(org.value))})
const publishedTasks=computed(()=>published.data.value?.results.filter(task=>Boolean(task.published_post))??[])
const short=useMutation({mutationFn:(id:string)=>createShortLink(id,crypto.randomUUID()),onSuccess:async()=>{message.value="短链接已创建。";await client.invalidateQueries({queryKey:analyticsKeys.short(org.value)})}})
const create=useMutation({mutationFn:async()=>{const task=publishedTasks.value.find(item=>item.id===taskId.value);if(!task?.published_post)throw new ApiError(0,"请选择已发布的内容。");const platform=await getPlatformContent(task.platform_content_id),master=await getMasterContent(platform.master_content_id),brief=await getBrief(master.brief_id),productId=brief.product_ids[0];if(!productId||!brief.landing_page_url)throw new ApiError(0,"内容来源缺少产品或落地页，无法创建追踪链接。");return createTrackingLink({destination:brief.landing_page_url,utm_source:utmSource.value,utm_medium:utmMedium.value,utm_campaign:utmCampaign.value,campaign_id:brief.campaign_id,platform_id:task.platform_id,product_id:productId,published_post_id:task.published_post.id},crypto.randomUUID())},onSuccess:async()=>{createOpen.value=false;message.value="追踪链接已创建。";await client.invalidateQueries({queryKey:analyticsKeys.tracking(org.value)})}})
const maxClicks=computed(()=>Math.max(1,...(summary.data.value?.results.map(row=>row.clicks)??[1])))
const err=(v:unknown)=>v instanceof ApiError?v.userMessage:"分析数据暂时无法加载，请稍后重试。"
async function copy(value:string){try{await navigator.clipboard.writeText(value);message.value="已复制链接。"}catch{message.value="复制失败，请手动选择链接。"}}
function reset(){start.value=iso(startDefault);end.value=iso(today);country.value=""}
</script>
<template><main class="page-stack"><header class="link-row"><div><p class="eyebrow">渠道成效</p><h1>数据看板</h1><p>查看聚合点击趋势，并管理已发布内容的追踪链接。</p></div><button class="primary-action" @click="createOpen=true">创建追踪链接</button></header><p v-if="message" role="status">{{ message }}</p><section class="filters" aria-label="分析筛选"><label>开始日期<input v-model="start" type="date"></label><label>结束日期<input v-model="end" type="date"></label><label>国家代码<input v-model="country" maxlength="2" placeholder="DE"></label><button @click="reset">恢复近 30 天</button></section><p v-if="summary.isPending.value" role="status">正在加载分析数据…</p><section v-else-if="summary.isError.value" class="panel" role="alert"><h2>分析数据没有加载成功</h2><p>{{ err(summary.error.value) }}</p><button @click="summary.refetch()">重新加载分析数据</button></section><template v-else><section class="metric panel" aria-label="总点击数" aria-live="polite"><span>总点击数</span><strong>{{ summary.data.value?.total_clicks??0 }}</strong><small>符合当前筛选条件</small></section><section v-if="summary.data.value?.results.length" class="panel"><h2>点击趋势</h2><div class="bars" aria-label="点击趋势图"><div v-for="row in summary.data.value.results" :key="`${row.date}-${row.platform_id}-${row.country}`" class="bar-row"><span>{{ row.date }}</span><span class="bar" :style="{width:`${Math.max(4,row.clicks/maxClicks*100)}%`}"></span><strong>{{ row.clicks }}</strong></div></div><div class="table-wrap"><table aria-label="渠道点击明细"><thead><tr><th>日期</th><th>国家</th><th>渠道</th><th>产品</th><th>点击</th></tr></thead><tbody><tr v-for="row in summary.data.value.results" :key="`${row.date}-${row.campaign_id}-${row.product_id}`"><td>{{ row.date }}</td><td>{{ row.country||'未知' }}</td><td>{{ row.platform_id }}</td><td>{{ row.product_id }}</td><td>{{ row.clicks }}</td></tr></tbody></table></div></section><section v-else class="panel"><h2>当前条件暂无点击</h2><p>尝试扩大日期范围或清除国家筛选。</p></section></template><section class="panel"><h2>追踪链接</h2><p v-if="tracking.isError.value" role="alert">{{ err(tracking.error.value) }} <button @click="tracking.refetch()">重新加载链接</button></p><p v-else-if="!tracking.data.value?.results.length">暂无追踪链接。发布内容后可在这里创建短链接。</p><article v-for="link in tracking.data.value?.results" :key="link.id" class="link-row"><div><strong>{{ link.utm_campaign }}</strong><p>{{ link.full_url }}</p></div><div class="actions"><button @click="copy(link.full_url)">复制</button><button @click="short.mutate(link.id)">创建短链接</button></div></article></section><section class="panel"><h2>短链接</h2><p v-if="shorts.isError.value" role="alert">{{ err(shorts.error.value) }}</p><article v-for="item in shorts.data.value?.results" :key="item.id" class="link-row"><code>{{ item.redirect_path }}</code><button @click="copy(item.redirect_path)">复制</button></article></section><div v-if="createOpen" class="modal-backdrop" @click.self="createOpen=false"><form class="modal panel" role="dialog" aria-modal="true" aria-labelledby="tracking-title" @submit.prevent="create.mutate()"><h2 id="tracking-title">创建追踪链接</h2><label>已发布内容<select v-model="taskId" required><option value="" disabled>请选择</option><option v-for="task in publishedTasks" :key="task.id" :value="task.id">{{ task.published_post?.external_id||task.id }}</option></select></label><label>来源<input v-model="utmSource" required placeholder="linkedin"></label><label>媒介<input v-model="utmMedium" required></label><label>活动标识<input v-model="utmCampaign" required></label><p>目标地址、活动、平台、产品与发布记录会从内容来源自动锁定。</p><p v-if="create.isError.value" role="alert">{{ err(create.error.value) }}</p><div class="actions"><button type="button" @click="createOpen=false">取消</button><button class="primary-action" :disabled="create.isPending.value||!publishedTasks.length">创建</button></div></form></div></main></template>
<style scoped>.filters{display:grid;grid-template-columns:repeat(4,1fr);gap:1rem;align-items:end}.filters label,.modal label{display:grid;gap:.35rem}.panel,.filters{padding:1.1rem;border:1px solid var(--border-color,#d8dee8);border-radius:1rem;background:white}.metric{display:grid;gap:.25rem}.metric strong{font-size:2.5rem;color:#005ba8}.bars{display:grid;gap:.5rem}.bar-row{display:grid;grid-template-columns:7rem minmax(2rem,1fr) 3rem;gap:.5rem;align-items:center}.bar{height:.8rem;background:#005ba8;border-radius:999px}.table-wrap{overflow-x:auto;margin-top:1rem}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:.65rem;border-bottom:1px solid #e5e9ef}.link-row,.actions{display:flex;justify-content:space-between;align-items:center;gap:1rem}.link-row p{overflow-wrap:anywhere}.actions{justify-content:flex-end}.modal-backdrop{position:fixed;inset:0;background:#0008;display:grid;place-items:center;padding:1rem;z-index:10}.modal{width:min(36rem,100%);display:grid;gap:1rem}@media(max-width:700px){.filters{grid-template-columns:1fr}.link-row{display:grid}.bar-row{grid-template-columns:6rem 1fr 2rem}}</style>
